INSERT INTO service_petition_details (service_description,service_description_localized,service_name,service_name_localized,service_login_url,service_login_url_localized,logo_uri,integration_environment,requester,type,service_id,comment,status,protocol,group_id,tenant,country,check_group_membership,require_vo_membership,rp_ensure_membership_desc,require_group_membership,rp_ensure_group_membership_desc,create_group,allow_registration,dynamic_registration,registration_url,aup_uri,organization_id,last_edited)
VALUES (${service_description},${service_description_localized},${service_name},${service_name_localized},${service_login_url},${service_login_url_localized},${logo_uri},${integration_environment},${requester},${type},${service_id},${comment},${status},${protocol},${group_id},${tenant},${country},${check_group_membership},${require_vo_membership},${rp_ensure_membership_desc},${require_group_membership},${rp_ensure_group_membership_desc},${create_group},${allow_registration},${dynamic_registration},${registration_url},${aup_uri},${organization_id},current_timestamp)
RETURNING *
